const D2ok=D2.filter(f=>{try{const d=f();return !(d.ans===-1);}catch(e){return false;}});
D2ok.forEach(f=>DRILLS.push(f));

// ================= WHAT TO EXPECT: predicted exam coverage =================
const EXPECT=[
 {sec:"A.1 Terminology & definitions",ev:"seen",w:"High",fmt:"Short conceptual MCQs (definition of an asset, expense, net income; who uses financial vs managerial accounting; forms of organization) and the accounting equation rearranged.",hot:["Assets = Liabilities + Equity and every rearrangement","Asset / liability / equity / revenue / expense definitions","Accrual vs cash basis; matching; conservatism","Financial vs managerial accounting users","Sole proprietorship vs partnership vs corporation liability"],use:"Learn (A.1, exam core) · Drills · Match (exam)"},
 {sec:"A.2 Recording transactions",ev:"seen",w:"High",fmt:"A transaction-analysis table (accounts + signed amounts, with a None trap), buyer-vs-seller questions (A/P vs A/R), which entry records X, and what is or is not an expense. Adjusting and closing entries were not on last year's set but are the core of the reading, so expect one or two.",hot:["Effects of each event on A, L, E (the table)","Unearned revenue: cash before performance is a liability","Paying on account is not an expense","Adjusting entries: accrued wages/interest, prepaid used, supplies used, depreciation","Closing entries zero the temporary accounts","Normal balances; what a trial balance does and does not catch"],use:"Transactions · Drills (A.2) · Story · Examples (faded entries)"},
 {sec:"A.3 Financial statements",ev:"seen",w:"High",fmt:"Numeric chains from one scenario (net income, ending retained earnings, ending liabilities, ending assets), revenue earned vs cash collected, what goes on which statement. Cash-flow classification and the indirect method are heavily emphasized in the reading, so expect them even though last year skipped them.",hot:["NI = revenues − expenses (dividends are not expenses)","Ending RE = beginning + NI − dividends","Change in assets = change in liabilities + change in equity","Which statement reports a given item","Operating / investing / financing classification","Indirect method: add back depreciation, adjust for working-capital changes","Multiple-step income statement subtotals"],use:"Drills (A.3) · Story (all three statements) · Statements · Build"},
 {sec:"A.4 Internal controls",ev:"inferred",w:"Medium",fmt:"Not on last year's practice set, but a full PRC study session with its own quiz items, so likely two to four conceptual MCQs: segregation-of-duties scenarios, COSO objectives, risk vocabulary, who is responsible.",hot:["Four duties to separate: authorize, record, custody, reconcile","Cashier / deposit / reconciliation violations","COSO: operations, reporting, compliance","Inherent vs control vs detection risk","Reasonable, not absolute, assurance (collusion, override, cost)","Board is ultimately responsible; management maintains"],use:"Drills (A.4) · Sort → Which control duty · Learn (A.4 exam core)"},
 {sec:"A.5 Daily finances",ev:"inferred",w:"Medium",fmt:"Working-capital reasoning rather than heavy math: what changes NWC, cash vs operating cycle, motives for holding cash, credit-policy trade-offs, inventory cost types, JIT.",hot:["NWC = current assets − current liabilities and what moves it","Operating cycle vs cash conversion cycle","Aggressive / conservative / matching policies","Carrying vs ordering vs stockout costs; JIT trade-off","Loosening credit: sales up, A/R up, bad debts up","Factoring with vs without recourse"],use:"Drills (A.5) · Learn (A.5 exam core)"},
 {sec:"B.1 Recognition & valuation",ev:"seen",w:"High",fmt:"Depreciation was on last year's set (straight-line, DDB concept, choosing units-of-production). The reading adds bad-debt estimates, inventory cost flow, sales discounts, revenue recognition timing and equity transactions; expect computations with a twist (salvage value, existing allowance balance, year 2 of DDB).",hot:["SL, DDB, SYD, units-of-production; book value; gain or loss on disposal","% of sales vs aging for bad debts; write-off has no income effect","FIFO vs LIFO COGS in rising prices","2/10, n/30 cash discounts","Revenue over time vs point in time; advances are liabilities","Stock dividends and treasury stock effects on equity"],use:"Drills (B.1) · Learn (B.1 exam core) · Sort → Revenue timing"},
 {sec:"B.2 Basic analysis",ev:"inferred",w:"Medium",fmt:"Short percentage questions: horizontal % change, vertical common-size %, and which of several items grew fastest in percentage terms.",hot:["(Current − prior) ÷ prior","Line ÷ sales (or ÷ total assets) for common-size","Compare percentages, not dollars"],use:"Drills (B.2) · Charts"},
 {sec:"B.3 Ratio analysis",ev:"inferred",w:"Medium-high",fmt:"Formula-and-compute questions, one ratio at a time, plus a few interpretation questions (which ratio a lender uses, what a falling inventory turnover suggests, how a transaction moves the current ratio).",hot:["Current and quick ratio; effect of a transaction on them","Debt ratio, debt-to-equity, times interest earned","Inventory and receivable turnover and their day counts","Gross, operating, net margin; ROA; ROE and leverage","Cash conversion cycle"],use:"Drills (B.3) · Diagrams → Ratio tree · Learn (B.3 exam core)"}
];
function drawExpect(){
  return `<div class="vinfo" style="width:min(1100px,100%)"><div class="vt">What to expect on the exam</div><div class="intro">Built from two sources: the previous year's practice set (what was actually asked) and the PRC reading for sections A and B (what the course says you must know). "Seen" means that section appeared on last year's set; "inferred" means it is in the required reading with its own quiz items but was not sampled last year, so it is a likely place for new questions. The Drills follow the sections ticked in the sidebar, and the Filter menu has an "exam core only" option that trims the deck to the ${window.FMAA_CORE?window.FMAA_CORE.size:""} cards most likely to be tested.</div>
  <div class="exgrid">${EXPECT.map(e=>`<div class="excard"><div class="exh"><b>${esc(e.sec)}</b><span class="tagx ${e.ev}">${e.ev==="seen"?"seen last year":"inferred from reading"}</span><span class="tagx w">${esc(e.w)} weight</span></div><div class="exf">${esc(e.fmt)}</div><ul class="exl">${e.hot.map(h=>`<li>${esc(h)}</li>`).join("")}</ul><div class="meta" style="text-align:left">Practice with: ${esc(e.use)}</div></div>`).join("")}</div>
  <div class="vt" style="margin-top:14px">Suggested loop</div><div class="intro">1. Tick all sections, Filter → exam core only, and run Learn until the cards are known (spaced repetition will bring them back). 2. Every session: one Drill set of 10 with all sections ticked, one Transactions set, one Story with all three statements on. 3. Twice a week: Test on all sections, then re-drill only the sections you missed by ticking just those. 4. The day before: Match (exam) and the Cheat Sheet for definitions, then Drills with B.1 and B.3 ticked, because those are where the numbers can surprise you.</div></div>${method("test-enhanced learning aimed at the predicted distribution, not the whole textbook evenly")}`;
}

let dr={qs:[],i:0,picked:[],done:false};
function drillPool(){const secs=ctx.state.secs;let p=DRILLS.filter(f=>secs.includes(f.sec));return p.length?p:DRILLS;}
function mkDrill(){const pool=drillPool();const f0=pool[Math.random()*pool.length|0];const d=f0();d.sec=f0.sec;if(d.choices)return d;
  const unit=d.unit||(d.ratio?"x":"$");const f=v=>unit==="$"?$$(v):unit==="%"?(Math.round(v*10)/10).toFixed(1)+"%":unit==="days"?fmt(v)+" days":v.toFixed(2);const seen=new Set([f(d.ans)]);const ds=[];for(const x of d.ds){if(typeof x==='number'&&isFinite(x)&&(x>0||unit==='%')&&!seen.has(f(x))){seen.add(f(x));ds.push(x);}}
  for(let k=0;ds.length<3&&k<60;k++){const base=d.ans||(unit==="$"?1000:unit==="days"?10:1);const x=base*(1+(Math.random()<0.5?-1:1)*(0.1+Math.random()*0.5));const y=unit==="$"?(Math.round(x/500)*500||500):unit==="days"?Math.round(x)||1:Math.round(x*100)/100;if(!seen.has(f(y))&&(y>0||unit==="%")){seen.add(f(y));ds.push(y);}}
  for(let k=1;ds.length<3;k++){const y=d.ans+k*(unit==="$"?1000:unit==="days"?5:unit==="%"?2.5:0.25);if(!seen.has(f(y))){seen.add(f(y));ds.push(y);}}
  const ch=shuffle([d.ans,...ds]);return {q:d.q,choices:ch.map(f),ans:ch.indexOf(d.ans),why:d.why,sec:d.sec};}
function newDrills(){dr.qs=Array.from({length:10},mkDrill);dr.i=0;dr.picked=[];dr.done=false;}
function drawDrills(){
  if(!dr.qs.length)newDrills();
  if(dr.done){const r=dr.picked.filter((p,i)=>p===dr.qs[i].ans).length;
    return `<div class="vinfo" style="width:min(900px,100%)"><div class="vt">Drill set finished: ${r}/10</div><div class="list" style="margin-top:8px"><table>${dr.qs.map((q,i)=>`<tr style="color:${dr.picked[i]===q.ans?"var(--good)":"var(--bad)"}"><td>${i+1}</td><td>${esc(q.q)}<div class="meta" style="text-align:left">${esc(q.why)}</div></td><td>${"ABCD"[dr.picked[i]]}</td><td>${"ABCD"[q.ans]}</td></tr>`).join("")}</table></div>
    <div class="controls"><button class="primary" id="drNew">New set of 10</button></div></div>${method("practice testing with computation: exam-style word problems, fresh numbers every time")}`;}
  const q=dr.qs[dr.i],p=dr.picked[dr.i];
  return `<div class="vinfo" style="width:min(900px,100%)"><div class="vt">Drill ${dr.i+1}/10 <span class="meta">· ${esc(q.sec||"")} · sections follow the sidebar ticks</span></div><div class="q" style="text-align:left">${esc(q.q)}</div>
  <div class="choices">${q.choices.map((c,i)=>`<div class="choice ${p!==undefined?(i===q.ans?"correct":i===p?"wrong":"dim"):""}" data-i="${i}"><span class="k">${"ABCD"[i]}</span><span>${esc(c)}</span></div>`).join("")}</div>
  ${p!==undefined?`<div class="explain">${esc(q.why)}</div>`:""}
  <div class="controls">${p!==undefined?`<button class="primary" id="drNext">${dr.i+1<10?"Next →":"Finish"}</button>`:""}<button id="drNew">New set</button></div></div>
  ${method("practice testing with computation: exam-style word problems, fresh numbers every time")}`;
}
function bindDrills(){const c=ctx.content;
  if(dr.picked[dr.i]===undefined)c.querySelectorAll(".choice").forEach(el=>el.onclick=()=>{dr.picked[dr.i]=+el.dataset.i;ctx.state.test.done++;if(+el.dataset.i===dr.qs[dr.i].ans)ctx.state.test.right++;ctx.save();render();});
  const nx=$("#drNext",c);if(nx)nx.onclick=()=>{if(dr.i+1<10)dr.i++;else dr.done=true;render();};
  const nw=$("#drNew",c);if(nw)nw.onclick=()=>{newDrills();render();};
}

// ================= MATCH, exam style: letters, with more definitions than terms =================
let mx={terms:[],defs:[],sel:{},checked:false};
function newMx(){let secs=ctx.state.secs.filter(x=>x!=="AB");if(!secs.length)secs=["A1","A2","A3","A4","A5","B1","B2","B3"];
  let pool_=(window.FMAA_CARDS||[]).map(c=>({sec:c[0],f:c[1],b:c[2]})).filter(c=>secs.includes(c.sec)&&c.f.length<60&&c.b.length<160);
  if(pool_.length<9)pool_=(window.FMAA_CARDS||[]).map(c=>({sec:c[0],f:c[1],b:c[2]})).filter(c=>c.f.length<60&&c.b.length<160);
  const cards=shuffle(pool_).slice(0,9);mx.terms=cards.slice(0,6).map((c,i)=>({t:c.f,d:c.b}));mx.defs=shuffle(cards.map(c=>c.b));mx.sel={};mx.checked=false;}
function drawMx(){if(!mx.terms.length)newMx();const L="ABCDEFGHIJK";const right=mx.checked?mx.terms.filter((t,i)=>mx.sel[i]===L[mx.defs.indexOf(t.d)]).length:0;
  return `<div class="vinfo" style="width:min(1000px,100%)"><div class="vt">Match the term and the definition (there are more definitions than terms)${mx.checked?` · ${right}/6`:""}</div>
  <div class="mxwrap"><div><table class="mxt">${mx.terms.map((t,i)=>{const ok=mx.checked&&mx.sel[i]===L[mx.defs.indexOf(t.d)];return `<tr class="${mx.checked?(ok?"txok":"txbad"):""}"><td><select data-i="${i}" ${mx.checked?"disabled":""}><option value="">__</option>${mx.defs.map((d,j)=>`<option ${mx.sel[i]===L[j]?"selected":""}>${L[j]}</option>`).join("")}</select></td><td>${i+1}. ${esc(t.t)}${mx.checked&&!ok?`<span class="meta"> → ${L[mx.defs.indexOf(t.d)]}</span>`:""}</td></tr>`;}).join("")}</table></div>
  <ol class="mxdefs" type="A">${mx.defs.map(d=>`<li>${esc(d)}</li>`).join("")}</ol></div>
  <div class="controls">${mx.checked?`<button class="primary" id="mxNew">New set →</button>`:`<button class="primary" id="mxChk">Check</button><button id="mxNew">New set</button>`}</div></div>${method("matching with distractors, the exam's format: extra definitions mean you must know each term, not eliminate")}`;}
function bindMx(){const c=ctx.content;c.querySelectorAll(".mxt select").forEach(s=>s.onchange=()=>{mx.sel[+s.dataset.i]=s.value;});
  const chk=$("#mxChk",c);if(chk)chk.onclick=()=>{mx.checked=true;render();};const nw=$("#mxNew",c);if(nw)nw.onclick=()=>{newMx();render();};}

function render(){
  const c=ctx.content;
  const opts=(o,cur,lab)=>`<select id="vpick">${Object.keys(o).map(k=>`<option value="${k}" ${cur===k?"selected":""}>${lab(k)}</option>`).join("")}</select>`;
  const ST=window.FMAA_STATEMENTS;const stMap=Object.fromEntries(ST.list);
  const picker={expect:"",drills:"",tx:"",mx:"",story:"",build:"",stmts:opts(stMap,pick.stmt,k=>stMap[k]),maps:opts(MAPS,pick.map,k=>MAPS[k][0]),diagrams:opts(D,pick.diagram,k=>D[k].title),anim:opts(ANIMS,pick.anim,k=>ANIMS[k][0]),charts:opts(CHARTS,pick.chart,k=>CHARTS[k][0]),sims:opts(SIMS,pick.sim,k=>SIMS[k].title+(ctx.state.visual&&ctx.state.visual[k]!=null?" · best "+ctx.state.visual[k]+"%":"")),match:""}[sub];
  const body={expect:drawExpect,drills:drawDrills,tx:drawTx,mx:drawMx,story:drawStory,build:drawBuild,stmts:()=>ST.render(pick.stmt,stSel,stQuiz)+`<div class="controls"><button id="stPrev">← Prev line</button><button class="primary" id="stNext">Next line →</button><button id="stQuiz" class="${stQuiz?"warn":""}">${stQuiz?"Show labels":"Hide labels (recall)"}</button></div>${method("worked example: read a complete statement line by line, then recall the labels from the numbers alone")}`,maps:drawMap,diagrams:drawDiagram,anim:()=>ANIMS[pick.anim][1](),charts:drawChart,sims:drawSim,match:drawMatch}[sub]();
  const TABS_ALL=[["expect","What to expect","predicted coverage and a study loop"],["drills","Drills","exam-style word problems, endless"],["tx","Transactions","effects on the accounting equation (exam table)"],["story","Story","turn a word problem into statements"],["stmts","Statements","read a full statement line by line"],["build","Build","sort accounts, assemble a mini balance sheet"],["mx","Match (exam)","terms to lettered definitions, with extras"],["maps","Mind maps","see how topics connect"],["diagrams","Diagrams","process flows, step by step"],["anim","Examples","worked and faded examples"],["charts","Charts","ratios and trends as pictures"],["sims","Sort","drag items into categories"],["match","Match","pair terms with meanings"]];
  const EXAM=["expect","drills","tx","story","mx"];const TABS=TABS_ALL.filter(t=>EXAM.includes(t[0])===(group==="exam"));if(!TABS.some(t=>t[0]===sub))sub=TABS[0][0];subs[group]=sub;
  const cur=TABS.find(t=>t[0]===sub);
  c.innerHTML=`<div class="stage" style="justify-content:flex-start;padding-top:4px"><div class="vtop"><div class="vtabs">${TABS.map(([k,l])=>`<button class="${sub===k?"on":""}" data-v="${k}">${l}</button>`).join("")}</div><div class="vcrumb"><b>${esc(cur[1])}</b><span class="meta">${esc(cur[2])}</span></div>${picker}</div>${body}</div>`;
  const nav=document.getElementById("visNav");if(nav){nav.innerHTML=`<h3>${group==="exam"?"Exam practice":"Visual activities"}</h3>${TABS.map(([k,l,d])=>`<button class="vnav ${sub===k?"on":""}" data-v="${k}"><b>${l}</b><span>${d}</span></button>`).join("")}`;
    nav.querySelectorAll(".vnav").forEach(b=>b.onclick=()=>{sub=b.dataset.v;subs[group]=sub;step=0;ui={};render();if(window.closeSide)window.closeSide();});}
  c.querySelectorAll(".vtabs button").forEach(b=>b.onclick=()=>{sub=b.dataset.v;subs[group]=sub;step=0;ui={};render();});
  const vp=$("#vpick",c);if(vp)vp.onchange=e=>{pick[{stmts:"stmt",maps:"map",diagrams:"diagram",anim:"anim",charts:"chart",sims:"sim"}[sub]]=e.target.value;step=0;ui={};stSel=null;sim={sel:null,placed:{},set:null};render();};
  if(sub==="stmts"){c.querySelectorAll(".sl.click").forEach(r=>r.onclick=()=>{stSel=+r.dataset.i;render();});
    const n=ST.count(pick.stmt),step_=d=>{let i=stSel==null?(d>0?-1:n):stSel;for(let t=0;t<n;t++){i=(i+d+n)%n;if(ST.hasE(pick.stmt,i))break;}stSel=i;render();const el=c.querySelector(".sl.on");if(el)el.scrollIntoView({block:"nearest"});};
    $("#stNext",c).onclick=()=>step_(1);$("#stPrev",c).onclick=()=>step_(-1);$("#stQuiz",c).onclick=()=>{stQuiz=!stQuiz;render();};}
  c.querySelectorAll(".vn").forEach(n=>n.onclick=()=>{if(sub==="maps"){ui.open[+n.dataset.i]=!ui.open[+n.dataset.i];}else step=+n.dataset.i;render();});
  c.querySelectorAll("[data-fam]").forEach(b=>b.onclick=()=>{step=+b.dataset.fam;ui.r=0;render();});
  c.querySelectorAll(".rchip[data-r]").forEach(b=>b.onclick=()=>{ui.r=+b.dataset.r;render();});
  const nx=$("#vnext",c),pv=$("#vprev",c);
  if(nx)nx.onclick=()=>{const max=sub==="diagrams"?(D[pick.diagram].nodes||[]).length||4:pick.anim==="bestport"?BP.length+1:pick.anim==="cashflow"?CF.length+1:99;step=(step+1)%max;render();};
  if(pv)pv.onclick=()=>{step=Math.max(0,step-1);render();};
  const rv=$("#vreveal",c);if(rv)rv.onclick=()=>{ui.reveal=1;render();};
  const ms=$("#mshow",c),mr=$("#mrecall",c);if(ms)ms.onclick=()=>{ui.recall=0;render();};if(mr)mr.onclick=()=>{ui.recall=1;ui.open={};render();};
  if(sub==="sims")bindSim();if(sub==="match")bindMatch();if(sub==="build")bindBuild();if(sub==="story")bindStory();if(sub==="tx")bindTx();if(sub==="drills")bindDrills();if(sub==="mx")bindMx();
  if(sub==="anim"&&pick.anim==="faded"){$("#fdr",c).onchange=e=>fade.dr=e.target.value;$("#fcr",c).onchange=e=>fade.cr=e.target.value;
    $("#fchk",c).onclick=()=>{const a=BP[fade.i][1];const ok=a.some(x=>x[1]&&x[0]===fade.dr)&&a.some(x=>x[2]&&x[0]===fade.cr);if(fade.res===null&&ok)fade.score++;fade.res=ok;render();};
    $("#fnext",c).onclick=()=>{fade.i=(fade.i+1)%BP.length;fade.dr=fade.cr="";fade.res=null;render();};$("#fprev",c).onclick=()=>{fade.i=(fade.i+BP.length-1)%BP.length;fade.dr=fade.cr="";fade.res=null;render();};}
  if(sub==="anim"&&pick.anim==="workout"){const inp=$("#ranswer",c);inp.oninput=e=>rw.ans=e.target.value;inp.onkeydown=e=>{if(e.key==="Enter")$("#rchk",c).click();};
    $("#rchk",c).onclick=()=>{const r=RATIOS[rw.order[rw.i%rw.order.length]],v=r.v();let a=parseFloat(rw.ans);if(isNaN(a))return;if(r.fam==="Profitability"){if(a>1)a=a/100;}const ok=Math.abs(a-v)<=Math.max(0.02*Math.abs(v),r.den===""?1:0.011);if(rw.res===null&&ok)rw.score++;rw.res=ok;render();};
    $("#rhint",c).onclick=()=>{ui.hint=1;render();};$("#rnext",c).onclick=()=>{rw.i++;rw.ans="";rw.res=null;ui.hint=0;render();};}
}
